const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// This function masks pixels based on the VNP46A2 Quality Flags.
// We are interested in high-quality, cloud-free nighttime observations.
// Bit 0: 0 = High-quality NTL retrieval. We only want this.
function qualityMask(image) {
  const quality = image.select('Mandatory_Quality_Flag');
  // Check if bit 0 is 0 (high quality).
  const highQuality = quality.bitwiseAnd(1).eq(0);
  return image.updateMask(highQuality);
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const airport = ee.Geometry.Point(85.8178, 20.2444); // Biju Patnaik Airport
  const saheedNagar = ee.Geometry.Point(85.848691, 20.290813);
  const band = 'DNB_BRDF_Corrected_NTL'; // BRDF-Corrected Nighttime Lights

  // Dates for comparison. Using a single day for each period.
  const date1 = '2019-04-30';
  const date2 = '2019-05-05';

  // 2. Data Acquisition & Check
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/VNP46A2');

  const img1Col = viirsCollection.filterDate(date1, ee.Date(date1).advance(1, 'day')).map(qualityMask);
  const img2Col = viirsCollection.filterDate(date2, ee.Date(date2).advance(1, 'day')).map(qualityMask);

  const img1ColSize = img1Col.size().getInfo();
  const img2ColSize = img2Col.size().getInfo();

  console.log(`Images found for ${date1}: ${img1ColSize}`);
  console.log(`Images found for ${date2}: ${img2ColSize}`);

  if (img1ColSize === 0 || img2ColSize === 0) {
    console.log('Evidence: No cloud-free images were found for one or both dates.');
    console.log('A: Yes');
    return;
  }

  // Use the first available image for each date range
  const image1 = ee.Image(img1Col.first()).select(band);
  const image2 = ee.Image(img2Col.first()).select(band);

  // 3. Processing & Calculation
  // Define a larger scale because VIIRS data is coarse (500m) and we're sampling a point.
  // Using a reducer with a small scale on a point can be unreliable.
  // We'll use a small buffer and a mean reducer to get a more stable value.
  const scale = 500;
  const airportBuffer = airport.buffer(scale / 2); // Buffer radius half of the pixel size
  const saheedNagarBuffer = saheedNagar.buffer(scale / 2);

  // Helper function to extract mean value and pixel count for a given geometry and image
  const extractStats = (image, geom, date) => {
    const stats = image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geom,
      scale: scale,
      maxPixels: 1e9
    });
    return ee.Dictionary({
      value: stats.get(band + '_mean'),
      count: stats.get(band + '_count'),
      date: date
    });
  };

  const airportStats1 = extractStats(image1, airportBuffer, date1).getInfo();
  const airportStats2 = extractStats(image2, airportBuffer, date2).getInfo();
  const saheedNagarStats1 = extractStats(image1, saheedNagarBuffer, date1).getInfo();
  const saheedNagarStats2 = extractStats(image2, saheedNagarBuffer, date2).getInfo();

  // 4. Validation & Final Answer
  // Check for C2: No Valid Pixels
  if (airportStats1.count === 0 || airportStats2.count === 0 || saheedNagarStats1.count === 0 || saheedNagarStats2.count === 0) {
    console.log(`Evidence: At least one location had 0 valid pixels after cloud masking.`);
    console.log(`Airport Pixels (${date1}/${date2}): ${airportStats1.count}/${airportStats2.count}`);
    console.log(`Saheed Nagar Pixels (${date1}/${date2}): ${saheedNagarStats1.count}/${saheedNagarStats2.count}`);
    console.log('A: Yes');
    return;
  }

  // Check for C3: Calculation Failure
  if (airportStats1.value === null || airportStats2.value === null || saheedNagarStats1.value === null || saheedNagarStats2.value === null) {
      console.log('Evidence: A calculation resulted in a null value.');
      console.log(`Airport values: ${airportStats1.value}, ${airportStats2.value}`);
      console.log(`Saheed Nagar values: ${saheedNagarStats1.value}, ${saheedNagarStats2.value}`);
      console.log('A: Yes');
      return;
  }

  const airportDecrease = airportStats1.value - airportStats2.value;
  const saheedNagarDecrease = saheedNagarStats1.value - saheedNagarStats2.value;

  console.log(`Airport Brightness (${date1}): ${airportStats1.value.toFixed(2)} nW/(cm^2 sr)`);
  console.log(`Airport Brightness (${date2}): ${airportStats2.value.toFixed(2)} nW/(cm^2 sr)`);
  console.log(`Saheed Nagar Brightness (${date1}): ${saheedNagarStats1.value.toFixed(2)} nW/(cm^2 sr)`);
  console.log(`Saheed Nagar Brightness (${date2}): ${saheedNagarStats2.value.toFixed(2)} nW/(cm^2 sr)`);
  console.log(`Airport brightness decrease: ${airportDecrease.toFixed(2)}`);
  console.log(`Saheed Nagar brightness decrease: ${saheedNagarDecrease.toFixed(2)}`);

  if (airportDecrease > saheedNagarDecrease) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or Analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
